from __future__ import (absolute_import, division, print_function)
__metaclass__ = type

# The cassandra.yaml keys a Cassandra release refuses to start with (its Config
# properties, generated by tools/gen_yaml_properties.py).

import os

import pytest
import yaml

from ansible_collections.community.cassandra.plugins.filter.cassandra_settings import (
    cassandra_yaml_rejected, yaml_rejected)
from ansible_collections.community.cassandra.plugins.module_utils import cassandra_yaml_properties as known

VARS = os.path.join(os.path.dirname(__file__), "..", "..", "..", "..", "roles", "cassandra_config", "vars", "main.yml")


@pytest.mark.parametrize("version", ["4.0.0", "4.0.21", "40x", "4.1.5", "4.1", "41x", "5.0.0", "5.0.9", "50x"])
def test_unknown_key_rejected_valid_key_accepted(version):
    assert yaml_rejected(["fake_option", "auto_bootstrap", "cluster_name"], version) == ["fake_option"]


def test_renamed_keys():
    # 4.1 renamed the *_in_ms / *_in_kb settings: the former names stay accepted (@Replaces)
    assert yaml_rejected(["key_cache_size_in_mb", "permissions_validity_in_ms"], "4.0.21") == []
    assert yaml_rejected(["key_cache_size_in_mb", "permissions_validity_in_ms"], "4.1.5") == []
    assert yaml_rejected(["key_cache_size_in_mb", "permissions_validity_in_ms"], "5.0.9") == []
    # the new names: 4.1 on
    assert yaml_rejected(["key_cache_size", "permissions_validity"], "4.0.21") == [
        "key_cache_size", "permissions_validity"]
    assert yaml_rejected(["key_cache_size", "permissions_validity"], "4.1.0") == []
    assert yaml_rejected(["key_cache_size", "permissions_validity"], "50x") == []


def test_version_specific_keys():
    # added in a patch release
    assert yaml_rejected(["batchlog_endpoint_strategy"], "4.0.14") == ["batchlog_endpoint_strategy"]
    assert yaml_rejected(["batchlog_endpoint_strategy"], "4.0.15") == []
    # the series alone: the keys no release of it accepts
    assert yaml_rejected(["batchlog_endpoint_strategy"], "40x") == []
    assert yaml_rejected(["batchlog_endpoint_strategy"], "4.0") == []
    # missing from one release only
    assert yaml_rejected(["otc_coalescing_strategy"], "4.0.2") == ["otc_coalescing_strategy"]
    assert yaml_rejected(["otc_coalescing_strategy"], "4.0.3") == []
    # removed in 5.0
    assert yaml_rejected(["native_transport_max_negotiable_protocol_version"], "4.1.12") == []
    assert yaml_rejected(["native_transport_max_negotiable_protocol_version"], "5.0.0") == [
        "native_transport_max_negotiable_protocol_version"]


def test_versions_not_known_judge_nothing():
    newer = "5.0.%d" % (known.LATEST["5.0"] + 1)  # the properties it added are not known
    assert yaml_rejected(["fake_option"], newer) == []
    assert yaml_rejected(["fake_option"], "3.11.4") == []
    assert yaml_rejected(["fake_option"], "") == []
    # a pre-release: the series' keys
    assert yaml_rejected(["fake_option", "batchlog_endpoint_strategy"], "5.0-rc1") == ["fake_option"]
    assert yaml_rejected(["fake_option", "batchlog_endpoint_strategy"], "5.0.0-rc1") == ["fake_option"]


def test_filter_takes_a_dict():
    assert cassandra_yaml_rejected({"fake_option": 42, "auto_bootstrap": False}, "4.1.5") == ["fake_option"]
    assert cassandra_yaml_rejected({}, "4.1.5") == []
    assert cassandra_yaml_rejected(None, "4.1.5") == []


def test_lists_cover_the_template_releases():
    """Moving a series' templates to a newer release needs the lists of that release too (tools/README.md)."""
    with open(VARS) as f:
        templates = yaml.safe_load(f)["_cassandra_config_template_versions"]
    for series, release in templates.items():
        assert int(str(release).split(".")[2]) <= known.LATEST[series], series


def test_dotted_key_judged_by_its_first_part():
    # 4.1+ sets a nested property that way (sstable.selected_format: bti)
    assert yaml_rejected(["sstable.selected_format"], "5.0.9") == []
    assert yaml_rejected(["fake.option"], "5.0.9") == ["fake.option"]
